lit = G.lit; BASE = M.BASE
def _pv():
    fw = X.FW; vk = lambda q: [int(x) for x in re.findall(r"_v(\d+)_(\d+)_(\d+)\.", q)[0]]
    spec = importlib.util.spec_from_file_location("pv", sorted(glob.glob(fw + "/03-tooling/backlog_pipeline_verify_v*.py"), key=vk)[-1]); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); m.STAGE_TYPES = m._load_stage_types(sorted(glob.glob(fw + "/01-ontologies/backlog_tbox_v*.ttl"), key=vk)[-1], table="v5"); return m
def digest(text, stage):
    g = rdflib.Graph(); g.parse(data=text, format="turtle"); return _pv().state_digest(g, "Stage_" + stage, rdflib.URIRef(BASE + "#Lineage4"), admitted=True, change_managed=True)
def set_status(t, st):
    pat = re.compile(r"(ex:Lineage4 a backlog:Lineage ;.*?backlog:hasLineageStatus backlog:)\w+( \.)", re.S); assert pat.search(t); return pat.sub(lambda m: m.group(1) + st + m.group(2), t, count=1)
def out(t, stage, name, consumes):
    c = ("    backlog:consumesOutput ex:%s ;\n" % consumes) if consumes else ""
    return ('\nex:%s a backlog:StageOutput ;\n    rdfs:label "Closure of the %s stage of the fourth lineage"@en ;\n    backlog:belongsToLineage ex:Lineage4 ;\n    backlog:outputOfStage backlog:Stage_%s ;\n%s    backlog:hasStateDigest "%s" ;\n    backlog:closedAtCommit "PENDING" .\n') % (name, stage, stage, c, digest(t, stage))
