def ev_backlog(t, prev):
    t = G.fill_re(t, "ex:Out4_Objective", prev); t = set_status(t, "LS_Backlogged"); now = M.now(); NB = "ex:Out4_Backlog"; L = []
    note = "Admitted at the Backlog stage of the fourth lineage, from the scope ex:Scope4 (verified gaps G1 to G7, owner's words of 2026-10-29). One criterion per unit (G133)."
    mem = {45: [], 46: []}
    for sid, title, dl, area, sess, cov, hrs, btxt, vtxt, deps, itn in STS:
        k = sid[3:]; bt = "TK_" + k + "_Build"; vt = "TK_" + k + "_Verify"; ac = "AC4_" + k; it = "ex:" + ITERS[itn][0]; mem[itn] += [sid, bt, vt]
        gh = ("Given the new files made for %s when the checks of this criterion are run on the evidence bridge then ALL of: (1) every file is new and no committed file is edited; (2) %s (3) results as printed; if any element fails the work is named failing. Source: the verified gaps G1 to G7 and the owner's words of 2026-10-29 in ex:Scope4." % (dl, vtxt))
        L.append('\nex:%s a backlog:AcceptanceCriterion ; rdfs:label %s@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:hasGherkinText %s ;\n    backlog:measuredWithTool ex:TS_ChapterCheck ;\n    backlog:measuredWithVersion "checks written by the executor as new files, run by the control on the evidence bridge" ;\n    backlog:satisfiedByArtifact "the new files cited by SHA-256, the logs of the runs, verified by the evidence bridge" ;\n    backlog:coveredByCase ex:TC4_%s_Passes, ex:TC4_%s_NotClaimed .\n' % (ac, lit("Criterion of " + title), lit(gh), k, k))
        L.append('ex:TC4_%(k)s_Passes a backlog:TestCase ; rdfs:label "Run the checks of the criterion"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:exercisesCriterion ex:%(a)s ; backlog:coversScenario ex:Spec4_Midterm_Pass ; backlog:runsOnData ex:Data4_%(k)s_Passing ;\n    backlog:hasCaseText "Run the checks of the criterion; they report no failure and exit 0." .\nex:TC4_%(k)s_NotClaimed a backlog:TestCase ; rdfs:label "Run the checks on a broken case and require that no pass is claimed"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:exercisesCriterion ex:%(a)s ; backlog:coversScenario ex:Spec4_Midterm_Fail ; backlog:runsOnData ex:Data4_%(k)s_Failing ;\n    backlog:hasCaseText "Run the checks on a fixture that breaks a convention, an item without a source or a paper with a doubtful mark, and require that nothing is claimed for it." .\nex:Data4_%(k)s_Passing a backlog:TestData ; rdfs:label "The new files whose checks pass when run"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:hasFixtureState "The new files of the task, for which every check of the criterion exits zero when the bridge runs it, and whose cited files equal their recorded SHA-256." .\nex:Data4_%(k)s_Failing a backlog:TestData ; rdfs:label "The broken case that fails the checks"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:hasFixtureState "A fixture that breaks one convention, whose answer is known in advance." .\n' % dict(k=k, a=ac))
        cv = "".join("    backlog:coversEntity ex:DE4_%s ; backlog:coversStage backlog:Stage_%s ;\n" % c for c in cov)
        L.append('\nex:%s a backlog:Story ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer %s ; backlog:admittedByOutput %s ;\n    backlog:hasInvestmentCategory backlog:Cat_NewCapability ;\n    backlog:asRole "SEN0401 instructor" ; backlog:wantsCapability %s ; backlog:soThat %s ;\n    backlog:satisfiesDeliverable ex:Del4_%s ; backlog:pursuesObjective ex:Obj4_Midterm ; backlog:hasAcceptanceCriterion ex:%s ;\n%s    backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasApplicableConcern backlog:Concern_Data ; backlog:responsible %s ;\n    backlog:decomposesInto ex:%s, ex:%s ;\n    backlog:hasState backlog:Proposed ;\n    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Scored by the ranking step of the same route." ;\n    backlog:hasAuditNote %s .\n' % (sid, lit(title), sid, lit(title), it, NB, lit(title[0].lower() + title[1:]), lit("the instructor holds two printed exams for chapters 1 to 8 and can grade the papers"), dl, ac, cv, G.EXEC, bt, vt, lit(note)))
        dd = (", ".join("ex:" + d for d in deps))
        for tid, tt, ttype, dp, st_ in ((bt, "Build: " + title, "Build", deps, "an executor session"), (vt, "Verify: " + title, "Verify", [bt], "the control")):
            full = (btxt if ttype == "Build" else vtxt) + " Planned session %s (an estimate, G120: the real start is recorded at work begun); about %.1f hours." % (sess if ttype == "Build" else "builder", hrs if ttype == "Build" else 1.0)
            L.append('\nex:%s a backlog:ExecutionTask ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer %s ; backlog:admittedByOutput %s ; backlog:responsible %s ;\n    backlog:hasInvestmentCategory backlog:Cat_%s ; backlog:hasTaskType backlog:TaskType_%s ; backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasState backlog:Proposed ;\n%s    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Ranked by its story\'s state; scoring both would double-count." ;\n    backlog:hasAuditNote %s .\n' % (tid, lit(tt), tid, lit(tt), it, NB, G.EXEC, "NewCapability" if ttype == "Build" else "Compliance", ttype, ("    backlog:dependsOn %s ;\n" % ", ".join("ex:" + d for d in dp)) if dp else "", lit(full)))
        L.append('ex:Plan4_%s a backlog:PlanningEvent ; rdfs:label "Planning of %s into iteration %d (planned, not started)"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:plannedAt "%s"^^xsd:dateTime ; backlog:plannedBy backlog:Builder ; backlog:plannedInto %s ;\n    backlog:plansItem ex:%s ; backlog:producesTask ex:%s, ex:%s ;\n    backlog:refinementProduces ex:Spec4_Midterm, ex:Spec4_Midterm_Pass, ex:Spec4_Midterm_Fail .\n' % (sid, sid, itn, now, it, sid, bt, vt))
        L.append("ex:%s backlog:standsAlone true .\n" % sid)
    for n, (itid, lab, st, en, goal) in ITERS.items():
        dur = "Planned by the lineage agent on 2026-10-29, NOT started: the start and the end are planned instants (%s to %s UTC), bounded by the tasks and the midterm of next week, not by a calendar; the ceremony is held when the iteration starts. Estimates, not measurements (G120)." % (st, en)
        L.append('ex:%s a backlog:Iteration ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:iterationStart "%s"^^xsd:dateTime ; backlog:iterationEnd "%s"^^xsd:dateTime ;\n    backlog:hasDurationSource %s ;\n    backlog:hasSprintGoal %s ;\n    backlog:hasMember %s .\n' % (itid, lit(lab), itid, st, en, lit(dur), lit(goal + " PLANNED, not started."), ", ".join("ex:" + x for x in mem[n])))
    L.append("ex:Obj4_Midterm backlog:metricMovableBy %s .\n" % ", ".join("ex:" + s[0] for s in STS))
    t += "\n" + "".join(L)
    return t + out(t, "Backlog", "Out4_Backlog", "Out4_Objective"), "fourth lineage, Backlog stage: seven stories with criteria, tasks and planning events in two planned iterations (45, 46); status LS_Backlogged."
def ev_fill(t, prev): return G.fill_re(t, "ex:Out4_Backlog", prev), "closedAtCommit of the Backlog output ex:Out4_Backlog set to the commit that closed it (%s)." % prev
def main():
    ev = sys.argv[1]; src = M.newest(); t = open(src, encoding="utf-8").read(); nxt, cur = M.next_version(src)
    fn = {"mission": lambda: ev_mission(t), "scope": lambda: ev_scope(t, sys.argv[2]), "goal": lambda: ev_goal(t, sys.argv[2]), "objective": lambda: ev_objective(t, sys.argv[2]), "backlog": lambda: ev_backlog(t, sys.argv[2]), "fill": lambda: ev_fill(t, sys.argv[2])}
    nt, comment = fn[ev](); print(os.path.basename(M.write_new(src, nt, nxt, cur, comment)))
if __name__ == "__main__": main()
